var MSS_Funds_Email_Utils = Class.create();
MSS_Funds_Email_Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    initialize: function() {},

    getAllTask: function() {
        try {
            //MSSFunds-4: Return all task
            gs.info('Testing This From Script Action');
            var fundFam = new GlideAggregate('x_hsb11_mss_fund_0_funds_task');
            fundFam.addEncodedQuery('fund_name.fund_family!=NULL^department!=NULL^state=1^statement_date!=NULL');
            fundFam.groupBy('fund_name.fund_family');
            fundFam.query();
            while (fundFam.next()) {
                var Dept = new GlideAggregate('x_hsb11_mss_fund_0_funds_task');
                Dept.addQuery('fund_name.fund_family', fundFam.getDisplayValue('fund_name.fund_family'));
                Dept.addEncodedQuery('fund_name.fund_family!=NULL^department!=NULL^state=1^statement_date!=NULL');
                Dept.groupBy('department');
                Dept.query();
                while (Dept.next()) {
                    var StmtDate = new GlideAggregate('x_hsb11_mss_fund_0_funds_task');
                    StmtDate.addEncodedQuery('fund_name.fund_family!=NULL^department!=NULL^state=1^statement_date!=NULL');
                    StmtDate.addQuery('department', Dept.getDisplayValue('department'));
                    StmtDate.groupBy('statement_date');
                    StmtDate.query();
                    var Taskarr = [],
                        arr = [];
                    while (StmtDate.next()) {
                        var record1 = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
                        record1.addQuery('statement_date', StmtDate.getDisplayValue('statement_date'));
                        record1.addEncodedQuery('fund_name.fund_family!=NULL^department!=NULL^state=1^statement_date!=NULL');
                        record1.query();

                        while (record1.next())
                            Taskarr.push(StmtDate.getDisplayValue('statement_date') + "--" + record1.number);
                        //gs.info(Taskarr);
                        for (var i = 0; i < Taskarr.length; i++)
                            arr.push(Taskarr[i].substr(-13));
                        var record = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
                        record.addEncodedQuery('fund_name.fund_family!=NULL^department!=NULL^state=1^statement_date!=NULL');
                        record.addEncodedQuery('numberIN' + arr);
                        record.query();
                        var receiverEmail;
                        var body = '<!DOCTYPE html><html> <div style="background-color: #ecf0f1;"> <p><span style="color: #000000; background-color: #ecf0f1; font-size: 10pt;">Hi Team</span></p> <p><span style="color: #000000; background-color: #ecf0f1; font-size: 10pt;">Could you please help to check and advise the cash & position</span></p> <p><span style="color: #000000; background-color: #ecf0f1; font-size: 10pt;">Cash breaks:</span></p> <br /> <table id= "table1" style="border-collapse: collapse; height: 112.409px; border-color: #ced4d9; table-layout:fixed; width:100% text-align: left; font-size: 14px; font-family: calibri; border-style: solid; float: left;" border="3"> <tbody> <tr style="height: 58.8068px; border-style: solid; background-color: #34495e;"> <td style="width: 8.78347%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Exception ID</span></td> <td style="width: 8.14699%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Client</span></td> <td style="width: 8.50514%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Portfolio Code</span></td> <td style="width: 8.17073%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">SET Name</span></td> <td style="width: 8.52888%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Statement Date</span></td> <td style="width: 8.52888%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Value Date</span></td> <td style="width: 8.14699%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Trade Date</span></td> <td style="width: 8.14699%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Item Type</span></td> <td style="width: 8.52888%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">CCY</span></td> <td style="width: 8.52888%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Amount</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 1</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 2</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 3</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 4</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">TRAN Code</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Break Resolved (Yes/No Selection)</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Comments</span></td> </tr>';
                        var body2 = '<!DOCTYPE html><html> <div style="background-color: #ecf0f1;"><p><span style="color: #000000; background-color: #ecf0f1; font-size: 10pt;">Position breaks:</span></p> <br /> <table id="table2" style="border-collapse: collapse; height: 112.409px; border-color: #ced4d9; table-layout:fixed; width:100% text-align: left; font-size: 14px; font-family: calibri; border-style: solid; float: left;" border="3"> <tbody> <tr style="height: 58.8068px; border-style: solid; background-color: #34495e;"> <td style="width: 8.78347%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Exception ID</span></td> <td style="width: 8.14699%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Client</span></td> <td style="width: 8.14699%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Category Code</span></td> <td style="width: 8.50514%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Portfolio Code</span></td> <td style="width: 8.17073%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">SET ID</span></td> <td style="width: 8.52888%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Item Type</span></td> <td style="width: 8.52888%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Asset Description</span></td> <td style="width: 8.14699%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Asset Code</span></td> <td style="width: 8.14699%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Quantity</span></td> <td style="width: 8.52888%; height: 58.8068px; border-style: solid;"><span style="color: #ffffff;">Statement Date</span></td> <td style="width: 8.52888%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Trade Date</span></td> <td style="width: 8.52888%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Local Market CCY</span></td> <td style="width: 8.52888%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Local Market Value</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 1</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 2</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 3</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Reference 4</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Break Resolved (Yes/No Selection)</span></td> <td style="width: 8.91077%; border-style: solid; height: 58.8068px;"><span style="color: #ffffff;">Comments</span></td> </tr>';
                        var body3 = '<div> <div style="font-family: calibri;"><br /></div> <div style="font-family: calibri;"><br /></div> <div style="font-family: calibri;"><b>Thanks &amp; Regards,</b></div> <div style="font-family: calibri;">Accounting &amp; Valuation| Securities Services, Guangdong</div> <div style="font-family: calibri;">Global Banking and Markets Centers | HSBC</div></div>';
                        while (record.next()) {
                            receiverEmail = record.department_email;
                            //if (record.state == '1') {
                            if (record.task_type == "cash") {
                                body = body + '<tr style="color: #000000;"> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.exception_id + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;input type="text""></td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.portfolio_code.getDisplayValue() + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;input type="text""></td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.statement_date + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.value_date + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.trade_date + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.item_type + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.ccy + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.amount + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference1 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference2 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference3 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference4 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;input type="text""></td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;input type="text""></td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.comments + '</td> </tr>';
                                //record.state = '202';
                                //record.update();
                            } else if (record.task_type == "position") {
                                body2 = body2 + '<tr style="color: #000000;"><td style="width: 8.78347%; height: 53.6023px; border-style: so-style: solid;">' + record.exception_id + '</td><td style="width: 8.78347%; height: 53.6023px; border-style: solid;input type="text""></td><td style="width: 8.78347%; height: 53.6023px; border-style: so-style: solid;">' + record.category_code + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.portfolio_code.getDisplayValue() + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.set_id + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.item_type + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.asset_description + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.asset_code + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.quantity + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.statement_date + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.trade_date + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.ccy + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.local_market_value + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference1 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference2 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference3 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.reference4 + '</td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;input type="text""></td> <td style="width: 8.78347%; height: 53.6023px; border-style: solid;">' + record.comments + '</td> </tr>';
                                //record.state = '202';
                                //record.update();
                            }
                            //}
                            Taskarr.splice();
                            arr.splice();
                        }
                        var getMaster = new GlideRecord('x_hsb11_mss_fund_0_funds_master');
                        getMaster.addEncodedQuery('fund_family=' + record1.fund_name.fund_family);
                        getMaster.query();
                        while (getMaster.next()) {
                            //gs.info("client" + getMaster.client);
                        }
                        var recCreate1 = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
                        recCreate1.initialize();
                        recCreate1.from = 'ubs.fundservices@hsbc.com.hk';
                        recCreate1.recipients = receiverEmail;
                        recCreate1.type = 'Outbound';
                        recCreate1.business_line = 'Funds';
                        recCreate1.api_response_from_qtrack = 'Sent-Ready';
                        recCreate1.subject = "[" + getMaster.client + ": " + record.fund_name.fund_family + " - " + record.department + "] [ Cut Off " + getMaster.sla_for_1st_chaser.getDisplayValue() + "] Cash & Position Break Query for valuation as of VD -" + record.statement_date;
                        //recCreate1.subject = getMaster.client + " " + record.fund_name.fund_family +" " +record.department+" "+ getMaster.sla_for_1st_chaser.getDisplayValue()+" "+"Cash & Position Break Query for valuation as of" + record.statement_date;
                        recCreate1.body = body + body2 + body3;
                        recCreate1.insert();
                    }
                }
            }
        } catch (ex) {
            var msg = ex.message;
            gs.error("Exception occured while creating email log");
        }
    },

    createChaserRecord: function(event) {
        var array = JSUtil.nil(event) ? this.getParameter('sysparm_sub') : event;
        //var array = event || this.getParameter('sub'); 
        gs.info("Testing Event - From Script Include -- Family" + array[0] + " -- Department -- " + array[1] + " -- Statement Date --" + array[2]);
    },

    createLogRecord: function() {

        function checkForState(id) {

            var getInfo = new GlideRecord('x_hsb11_mss_fund_0_funds_master');
            getInfo.addEncodedQuery('number', id);
            getInfo.query();
            while (getInfo.next()) {
                //gs.info("client" + getInfo.client);
            }

            var tableHTML = this.getParameter('sysparm_tableHTML');
            gs.info("From Script Inlude" + tableHTML);
            var parsedData = JSON.parse(tableHTML);
            gs.info("From Script Inlude" + parsedData.System1 + "-" + parsedData['System1']);
            //var table 	= '<!DOCTYPE html><html><table id="inputTable"><thead><tr><th></th><th>Corporate Action Request / Enquiry Form</th><th></th></tr></thead><tbody><tr><td></td><td></td><td>Remarks</td></tr><tr><td>System</td><td> '+ parsedData.system1 + ' </td> <td>' + jsonobj.system2 + '</td></tr><tr> <td>Request / Enquiry Category</td> <td>' + jsonobj.REC1 + '</td> <td>' + jsonobj.REC2 + '</td> </tr> <tr> <td>Request / Enquiry Type</td> <td> '+ jsonobj.RET1 + '</td> <td> '+ jsonobj.RET2 + '</td> </tr> <tr> <td>Contact Person Name</td> <td>'+ jsonobj.Contact1 + '</td>' + jsonobj.Contact2 + '</td> </tr> <tr> <td>CA Ref (if available)</td> <td>' + jsonobj.CA1+ '</td> <td>' + jsonobj.CA2 + '</td> </tr> <tr> <td>Fund ID</td> <td>'+ jsonobj.FundID1 +'</td> <td>'+jsonobj.FundID2+'</td></tr> <tr> <td>Event Type</td> <td>'+jsonobj.Event1+'</td> <td>'+jsonobj.Event2+'</td> </tr> <tr> <td>Service provided to the account</td> <td>'+jsonobj.service1+'</td> <td>'+jsonobj.service2+'</td> </tr> <tr> <td>Security ID in A and V System</td> <td>'+jsonobj.security1+'</td> <td>'+jsonobj.security2+'</td> </tr> <tr> <td>ISIN (if available)</td> <td>'+jsonobj.ISIN1+'</td> <td>'+jsonobj.ISIN2+'</td> </tr> <tr> <td>Security Name</td> <td>'+jsonobj.Sname1+'</td> <td>'+jsonobj.Sname2+'</td> </tr> <tr> <td>Client Name</td> <td>'+jsonobj.Cname1+'</td> <td>'+jsonobj.Cname2+'</td> </tr> <tr> <td>Ex-date</td> <td>'+jsonobj.exdate1+'</td> <td>'+jsonobj.exdate2+'</td> </tr> <tr> <td>Settlement Date</td> <td>'+jsonobj.Sdate1+'</td> <td>'+jsonobj.Sdate2+'</td> </tr> <tr> <td>Request Requirement / Enquiry Description</td> <td>'+jsonobj.request1+'</td> <td>'+jsonobj.request2+'</td> </tr> <tr> <td>Expected Completion Deadline</td> <td>'+jsonobj.edeadline1+'</td> <td>'+jsonobj.edeadline2+'</td> </tr> <tr> <td>Supporting Documents / Screen Shot</td> <td>'+jsonobj.sdoc1+'</td> <td>'+jsonobj.sdoc2+'</td> </tr> <tr> <td>Root cause (to be updated by GC CA)</td> <td>'+jsonobj.cause1+'</td> <td>'+jsonobj.cause2+'</td> </tr> <tr> <td>Status (to be updated by GC CA)</td> <td>'+jsonobj.status1+'</td> <td>'+jsonobj.status2+'</td> </tr> <tr> <td>Issue Identified (to be updated by GC CA)</td> <td>'+jsonobj.issue1+'</td> <td>'+jsonobj.issue2+'</td> </tr> <tr> <td>Solution / Action Taken (to be updated by GC CA)</td> <td>'+jsonobj.solution1+'</td> <td>'+jsonobj.solution1+'</td> </tr> <tr> <td>MF Transaction Reference# (Optional)</td> <td>'+jsonobj.mftrans1+'</td> <td>'+jsonobj.mftrans2+'</td> </tr> </tbody> </table> </body></html>';
            var table = '<!DOCTYPE html><html><table id="inputTable"><thead><tr><th></th><th>Corporate Action Request / Enquiry Form</th><th></th></tr></thead><tbody><tr><td></td><td></td><td>Remarks</td></tr><tr><td>System</td><td> ' + parsedData.System1 + ' </td> <td>' + parsedData.System2 + '</td></tr><tr> <td>Request / Enquiry Category</td> <td>' + parsedData.REC1 + '</td> <td>' + parsedData.REC2 + '</td> </tr> <tr> <td>Request / Enquiry Type</td> <td> ' + parsedData.RET1 + '</td> <td> ' + parsedData.RET2 + '</td> </tr> <tr> <td>Contact Person Name</td> <td>' + parsedData.Contact1 + '</td>' + parsedData.Contact2 + '</td> </tr> <tr> <td>CA Ref (if available)</td> <td>' + parsedData.CA1 + '</td> <td>' + parsedData.CA2 + '</td> </tr> <tr> <td>Fund ID</td> <td>' + parsedData.FundID1 + '</td> <td>' + parsedData.FundID2 + '</td></tr> <tr> <td>Event Type</td> <td>' + parsedData.Event1 + '</td> <td>' + parsedData.Event2 + '</td> </tr> <tr> <td>Service provided to the account</td> <td>' + parsedData.service1 + '</td> <td>' + parsedData.service2 + '</td> </tr> <tr> <td>Security ID in A and V System</td> <td>' + parsedData.security1 + '</td> <td>' + parsedData.security2 + '</td> </tr> <tr> <td>ISIN (if available)</td> <td>' + parsedData.ISIN1 + '</td> <td>' + parsedData.ISIN2 + '</td> </tr> <tr> <td>Security Name</td> <td>' + parsedData.Sname1 + '</td> <td>' + parsedData.Sname2 + '</td> </tr> <tr> <td>Client Name</td> <td>' + parsedData.Cname1 + '</td> <td>' + parsedData.Cname2 + '</td> </tr> <tr> <td>Ex-date</td> <td>' + parsedData.exdate1 + '</td> <td>' + parsedData.exdate2 + '</td> </tr> <tr> <td>Settlement Date</td> <td>' + parsedData.Sdate1 + '</td> <td>' + parsedData.Sdate2 + '</td> </tr> <tr> <td>Request Requirement / Enquiry Description</td> <td>' + parsedData.request1 + '</td> <td>' + parsedData.request2 + '</td> </tr> <tr> <td>Expected Completion Deadline</td> <td>' + parsedData.edeadline1 + '</td> <td>' + parsedData.edeadline2 + '</td> </tr> <tr> <td>Supporting Documents / Screen Shot</td> <td>' + parsedData.sdoc1 + '</td> <td>' + parsedData.sdoc2 + '</td> </tr> <tr> <td>Root cause (to be updated by GC CA)</td> <td>' + parsedData.cause1 + '</td> <td>' + parsedData.cause2 + '</td> </tr> <tr> <td>Status (to be updated by GC CA)</td> <td>' + parsedData.status1 + '</td> <td>' + parsedData.status2 + '</td> </tr> <tr> <td>Issue Identified (to be updated by GC CA)</td> <td>' + parsedData.issue1 + '</td> <td>' + parsedData.issue2 + '</td> </tr> <tr> <td>Solution / Action Taken (to be updated by GC CA)</td> <td>' + parsedData.solution1 + '</td> <td>' + parsedData.solution1 + '</td> </tr> <tr> <td>MF Transaction Reference# (Optional)</td> <td>' + parsedData.mftrans1 + '</td> <td>' + parsedData.mftrans2 + '</td> </tr> </tbody> </table> </body></html>';




            var logGr = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
            logGr.initialize();
            logGr.body = table;
            logGr.from = 'mss.fa.asp.shared.mailbox@noexternalmail.hsbc.com';
            logGr.recipients = 'sd.enquiry.ca.hss@hsbc.com.hk';
            logGr.copied = 'ubs.fundservices@hsbc.com.hk';
            logGr.type = 'Outbound';
            logGr.subject = getInfo.client + getInfo.sla_for_1st_chaser;
            logGr.insert();

            var xmlResponse = new GlideXML();
            xmlResponse.addNote('answer', 'record created');
            xml.xmlResponse.toString();

            return "record created";
        }

    },

    type: 'MSS_Funds_Email_Utils'
});
